EffDist(e):
  if e = Atom(w): return w
  if e = Series(e1,e2): return EffDist(e1) + EffDist(e2)
  if e = Parallel(e1,e2): return min(EffDist(e1), EffDist(e2))

TropElim(D, B, I):
  for v in I:
    for i,j in [1..n]:
      D[i][j] = min(D[i][j], D[i][v]+D[v][j])
  return D[B,B]
